def ring_router(operations):
    positions, names = [], []
    where = {}
    results = []
    for operation in operations:
        if operation[0] == 'add':
            name, position = operation[1:]
            at = bisect_left(positions, position)
            if name in where or (at < len(positions) and positions[at] == position):
                results.append(False)
            else:
                positions.insert(at, position)
                names.insert(at, name)
                where[name] = position
                results.append(True)
        elif operation[0] == 'remove':
            name = operation[1]
            if name not in where:
                results.append(False)
