def task_order(tasks, prerequisites):
    blocked = [0] * tasks
    unlocks = [[] for _ in range(tasks)]
    for before, after in prerequisites:
        unlocks[before].append(after)
        blocked[after] += 1
    heap = []
    for task in range(tasks):
        if blocked[task] == 0:
            heappush(heap, task)
    order = []
    while heap:
        task = heappop(heap)
        order.append(task)
        for following in unlocks[task]:
