def tile_pop(weights, tolerance):
    n = len(weights)
    # Column j + 1 represents the inclusive right endpoint j.
    clear = [[False] * (n + 1) for _ in range(n + 1)]
    best = [[0] * (n + 1) for _ in range(n + 1)]
    prefix = [0]
    for weight in weights:
        prefix.append(prefix[-1] + weight)
    for i in range(n + 1):
        clear[i][i] = True
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            can_clear = False
            most = best[i + 1][j + 1]
            for k in range(i + 1, j + 1, 2):
                if abs(weights[i] - weights[k]) > tolerance:
                    continue
                if not clear[i + 1][k]:
                    continue
                if clear[k + 1][j + 1]:
                    can_clear = True
                candidate = prefix[k + 1] - prefix[i] + best[k + 1][j + 1]
                most = max(most, candidate)
            clear[i][j + 1] = can_clear
            best[i][j + 1] = most
    return best[0][n]

