        nonlocal best
        if r == rows - 1 and c == cols - 1:
            best = min(best, paid)
            return
        if r + 1 < rows:
            walk(r + 1, c, paid + grid[r + 1][c], slide_used)
        if c + 1 < cols:
            walk(r, c + 1, paid + grid[r][c + 1], slide_used)
        if not slide_used:
