                walk(r, target, paid, True)
    walk(0, 0, grid[0][0], False)
    return best

def toll_slide(grid):
    rows, cols = len(grid), len(grid[0])
    infinity = float('inf')
    plain = [[infinity] * cols for _ in range(rows)]
    slid = [[infinity] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            toll = grid[r][c]
            if r == 0 and c == 0:
                plain[0][0] = toll
                continue
            p = s = infinity
            if r > 0:
                p, s = min(p, plain[r - 1][c]), min(s, slid[r - 1][c])
            if c > 0:
                p, s = min(p, plain[r][c - 1]), min(s, slid[r][c - 1])
            plain[r][c], slid[r][c] = p + toll, s + toll
            for origin in range(c):
                slid[r][c] = min(slid[r][c], plain[r][origin])
    return min(plain[-1][-1], slid[-1][-1])

