def trail_gain(heights):
    best = 0
    for i in range(len(heights)):
        for j in range(i + 1, len(heights)):
            best = max(best, heights[j] - heights[i])
    return best

def twin_xor(values):
    best = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            best = max(best, values[i] ^ values[j])
    return best

def twin_xor(values):
    zero, one = [0], [0]
    def insert(value):
        node = 0
        for bit in range(30, -1, -1):
            side = one if (value >> bit) & 1 else zero
            if not side[node]:
                side[node] = len(zero)
                zero.append(0)
                one.append(0)
            node = side[node]
    def best_for(value):
        node = result = 0
        for bit in range(30, -1, -1):
            want, fallback = (zero, one) if (value >> bit) & 1 else (one, zero)
            if want[node]:
                result |= 1 << bit
                node = want[node]
            else:
                node = fallback[node]
        return result
    insert(values[0])
    best = 0
    for i in range(1, len(values)):
        best = max(best, best_for(values[i]))
        insert(values[i])
    return best

def typo_distance(typed, intended):
    def distance(i, j):
        if i == len(typed):
            return len(intended) - j
        if j == len(intended):
            return len(typed) - i
        if typed[i] == intended[j]:
            return distance(i + 1, j + 1)
        return 1 + min(distance(i + 1, j + 1), distance(i + 1, j), distance(i, j + 1))
    return distance(0, 0)

def typo_distance(typed, intended):
    previous = list(range(len(intended) + 1))
    for i in range(1, len(typed) + 1):
        current = [i]
        for j in range(1, len(intended) + 1):
            if typed[i - 1] == intended[j - 1]:
                current.append(previous[j - 1])
            else:
                current.append(1 + min(previous[j - 1], previous[j], current[j - 1]))
        previous = current
    return previous[-1]

def vault_account(operations):
    history, results = [], []
    for operation in operations:
        if operation[0] == 'deposit':
            history.append(operation[1])
        elif operation[0] == 'withdraw':
            success = sum(history) >= operation[1]
            if success:
                history.append(-operation[1])
            results.append(success)
        else:
            results.append(sum(history))
    return results

class Vault:
    def __init__(self):
        self._balance = 0

    def deposit(self, amount):
        self._balance += amount

    def withdraw(self, amount):
        if amount > self._balance:
            return False
        self._balance -= amount
        return True

    def balance(self):
        return self._balance

def vault_account(operations):
    vault = Vault()
    results = []
    for operation in operations:
        if operation[0] == 'deposit':
            vault.deposit(operation[1])
        elif operation[0] == 'withdraw':
            results.append(vault.withdraw(operation[1]))
        else:
            results.append(vault.balance())
    return results

def warehouse_routes(grid):
    rows, cols = len(grid), len(grid[0])
    def walk(r, c):
        if r >= rows or c >= cols or grid[r][c] == '#':
            return 0
        if r == rows - 1 and c == cols - 1:
            return 1
        return (walk(r + 1, c) + walk(r, c + 1)) % 1000000007
    return walk(0, 0)

def warehouse_routes(grid):
    cols = len(grid[0])
    ways = [0] * cols
    ways[0] = int(grid[0][0] == '.')
    for row in grid:
        for c in range(cols):
            if row[c] == '#':
                ways[c] = 0
            elif c > 0:
                ways[c] = (ways[c] + ways[c - 1]) % 1000000007
    return ways[-1]

def warmer_wait(temps):
    wait = [0] * len(temps)
    for day in range(len(temps)):
        for later in range(day + 1, len(temps)):
            if temps[later] > temps[day]:
                wait[day] = later - day
                break
    return wait

def warmer_wait(temps):
    wait = [0] * len(temps)
    pending = []
    for day, temperature in enumerate(temps):
        while pending and temps[pending[-1]] < temperature:
            earlier = pending.pop()
            wait[earlier] = day - earlier
        pending.append(day)
    return wait

def watchtower_placements(size):
    def safe(assignment):
        for a in range(len(assignment)):
            for b in range(a + 1, len(assignment)):
                if abs(assignment[a] - assignment[b]) == b - a:
                    return False
        return True
    def permute(prefix, remaining):
        if not remaining:
            return int(safe(prefix))
        total = 0
        for i, column in enumerate(remaining):
            total += permute(prefix + [column], remaining[:i] + remaining[i + 1:])
        return total
    return permute([], list(range(size)))

def word_groups(words):
    def signature(word):
        return ''.join(sorted(word))
    groups = []
    for word in words:
        for group in groups:
            if signature(group[0]) == signature(word):
                group.append(word)
                break
        else:
            groups.append([word])
    for group in groups:
        group.sort()
    groups.sort(key=lambda group: group[0])
    return groups

def word_groups(words):
    groups = {}
    for word in words:
        key = ''.join(sorted(word))
        groups.setdefault(key, []).append(word)
    result = [sorted(group) for group in groups.values()]
    result.sort(key=lambda group: group[0])
    return result

def worn_tiles(length, passes, limit):
    scrubbed = [0] * length
    for start, end in passes:
        for tile in range(start, end + 1):
            scrubbed[tile] += 1
    return sum(count >= limit for count in scrubbed)

def worn_tiles(length, passes, limit):
    opens = sorted(start for start, _ in passes)
    closes = sorted(end + 1 for _, end in passes)
    i = j = active = at = worn = 0
    while i < len(opens) or j < len(closes):
        if j >= len(closes) or (i < len(opens) and opens[i] < closes[j]):
            edge = opens[i]
        else:
            edge = closes[j]
        if active >= limit:
            worn += edge - at
        at = edge
        while i < len(opens) and opens[i] == edge:
            active += 1
            i += 1
        while j < len(closes) and closes[j] == edge:
            active -= 1
            j += 1
    return worn

def worn_tiles(length, passes, limit):
    change = [0] * (length + 1)
    for start, end in passes:
        change[start] += 1
        change[end + 1] -= 1
    running = worn = 0
    for tile in range(length):
        running += change[tile]
        if running >= limit:
            worn += 1
    return worn

def zero_tail(numbers, base):
    product = 1
    for value in numbers:
        product *= value
    zeros = 0
    while product % base == 0:
        product //= base
        zeros += 1
    return zeros

def zero_tail(numbers, base):
    remaining = base
    answer = float('inf')
    prime = 2
    while remaining > 1:
        if prime * prime > remaining:
            prime = remaining
        if remaining % prime == 0:
            needed = 0
            while remaining % prime == 0:
                remaining //= prime
                needed += 1
            available = 0
            for value in numbers:
                rest = value
                while rest % prime == 0:
                    rest //= prime
                    available += 1
            answer = min(answer, available // needed)
        prime += 1
    return answer
